server {
    listen 8443 ssl default_server;
    listen [::]:8443 ssl default_server;

    server_name localhost;

    ssl_certificate /etc/nginx/ssl/cert.pem;
    ssl_certificate_key /etc/nginx/ssl/key.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Disable HSTS for testing
    add_header Strict-Transport-Security "max-age=0" always;

    # Main branch root
    location / {
        alias /opt/deployments/main/;
        index index.html;
        try_files $uri $uri/ =404;
    }

    # Dev branch under /dev
    location /dev/ {
        alias /opt/deployments/dev/;
        index index.html;
        try_files $uri $uri/ =404;
    }

    # Allow direct access to index.html
    location /index.html {
        alias /opt/deployments/main/index.html;
    }

    location /dev/index.html {
        alias /opt/deployments/dev/index.html;
    }
}

